let introTimer=null,introDone=null;function finishBattleIntro(){clearTimeout(introTimer);$('battleIntro').classList.remove('on');$('battleIntro').classList.add('h');$('battleIntro').setAttribute('aria-hidden','true');showBattlePage();hud();sync();$('bt').classList.add('on');setTimeout(()=>$('bt').classList.remove('on'),950);stopLobbyAmbience();cue('battle');feed('All combatants were ready. The battle began.');if(introDone){let fn=introDone;introDone=null;fn()}}
